{"path": "task.py", "content": "from collections import deque

def grid_distance(grid, start, end):
    # grid: 2D list where 1 means blocked, 0 means free
    # start, end: (row, col) tuples
    rows = len(grid)
    if rows == 0:
        return None
    cols = len(grid[0])
    # Check bounds
    sr, sc = start
    er, ec = end
    if sr < 0 or sr >= rows or sc < 0 or sc >= cols:
        return None
    if er < 0 or er >= rows or ec < 0 or ec >= cols:
        return None
    # Check if start or end is blocked
    if grid[sr][sc] == 1 or grid[er][ec] == 1:
        return None
    if start == end:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    q = deque()
    q.append((sr, sc, 0))
    visited[sr][sc] = True
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while q:
        r, c, d = q.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 0:
                if (nr, nc) == (er, ec):
                    return d + 1
                visited[nr][nc] = True
                q.append((nr, nc, d + 1))
    return None
"}

